 rows.sort((a,b)=>{for(let i=0;i<levels.length;i++){const x=a.keys[i],y=b.keys[i];if(x===y)continue;if(x==='')return 1;if(y==='')return -1;const order=typeof x==='number'&&typeof y==='number'?x-y:String(x).localeCompare(String(y),'es',{numeric:true,sensitivity:'base'});if(order)return order*levels[i].direction;}return a.r-b.r;});
