 if(refs.length===1){const [r,c]=coords[0];if(r>0&&typeof value(sheet,address(r-1,c))==='number'){let first=r-1;while(first>0&&typeof value(sheet,address(first-1,c))==='number')first--;source=address(first,c)+':'+address(r-1,c);}else if(c>0&&typeof value(sheet,address(r,c-1))==='number'){let first=c-1;while(first>0&&typeof value(sheet,address(r,first-1))==='number')first--;source=address(r,first)+':'+address(r,c-1);}else throw Error('No se encontró un bloque numérico encima ni a la izquierda.');target=refs[0];}
